package com.salespunch360.mobile.ui.account.accounting
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun ChartOfAccountsScreen(padding:PaddingValues,costCentres:Boolean=false,vm:AccountAccountingViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;val rows=s.data.array(if(costCentres)"costCentres" else "ledgerAccounts").map{it.jsonObject}.filter{it.toString().contains(s.query,true)};Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search code, account or group")},modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton({vm.editor(if(costCentres)"cost-centres" else "ledgers")}){Icon(Icons.Default.Add,"New ledger")}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(rows,key={it.str("id")}){x->ListItem(headlineContent={Text("${x.str("code")} · ${x.str("name")}",fontWeight=FontWeight.Bold)},supportingContent={Text("${x.str("accountClass")} · ${x.str("normalBalance")}${if(x["isSystem"]?.jsonPrimitive?.booleanOrNull==true)" · Protected system account" else ""}")},trailingContent={Text("₹${x.str("balance")}")})}}};if(s.editor=="ledgers")LedgerDialog({vm.editor(null)}){vm.save("ledgers",it)};if(s.editor=="cost-centres")CostCentreDialog({vm.editor(null)}){vm.save("cost-centres",it)}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun LedgerDialog(close:()->Unit,save:(JsonObject)->Unit){var code by remember{mutableStateOf("")};var name by remember{mutableStateOf("")};var cls by remember{mutableStateOf("ASSET")};var normal by remember{mutableStateOf("DEBIT")};var open by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=close,title={Text("New posting account")},text={Column{OutlinedTextField(code,{code=it},label={Text("Code")});OutlinedTextField(name,{name=it},label={Text("Name")});ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(cls,{},readOnly=true,label={Text("Account group")},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){listOf("ASSET","LIABILITY","EQUITY","INCOME","EXPENSE").forEach{v->DropdownMenuItem({Text(v)},{cls=v;normal=if(v in listOf("LIABILITY","EQUITY","INCOME"))"CREDIT" else "DEBIT";open=false})}}}}},confirmButton={Button(enabled=code.isNotBlank()&&name.isNotBlank(),onClick={save(buildJsonObject{put("code",code);put("name",name);put("accountClass",cls);put("normalBalance",normal);put("allowPosting",true)})}){Text("Create")}},dismissButton={TextButton(close){Text("Cancel")}})}

@Composable private fun CostCentreDialog(close:()->Unit,save:(JsonObject)->Unit){var code by remember{mutableStateOf("")};var name by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("New cost centre")},text={Column{OutlinedTextField(code,{code=it},label={Text("Code")});OutlinedTextField(name,{name=it},label={Text("Name")})}},confirmButton={Button(enabled=code.isNotBlank()&&name.isNotBlank(),onClick={save(buildJsonObject{put("code",code);put("name",name)})}){Text("Create")}},dismissButton={TextButton(close){Text("Cancel")}})}
